#include <iostream>
#include <cstring>
#include <queue>
using namespace std;

struct Point{int r,c,dis;};

const int dr[4]={-1,0,1,0},dc[4]={0,-1,0,1};
queue<Point> bfsQueue;
char input[15];
int totalNodes,sinkNode,m,limit,totalPath,pred[202],dist[202],height[202],gap[203],cap[202][202],flow[202][202],path[202];
bool gridVis[12][12],origGrid[12][12],pathFound;

void augmentPath(int u,int bottleneck){
  if(u==sinkNode){
    pred[0]=bottleneck;pathFound=true;return;
  }
  int minHeight=sinkNode+2;
  for(int v=0;v<=sinkNode+1;++v){
    if(flow[u][v]<cap[u][v]){
      minHeight=min(minHeight,height[v]);
      if(height[u]==height[v]+1){
        path[++totalPath]=v;
        augmentPath(v,min(bottleneck,cap[u][v]-flow[u][v]));
        if(!gridVis[0][0]||pathFound)return;
        path[totalPath--]=0;
      }
    }
    if(flow[v][u]>0){
      minHeight=min(minHeight,height[v]);
      if(height[u]==height[v]+1){
        path[++totalPath]=-v;
        augmentPath(v,min(bottleneck,flow[v][u]));
        if(!gridVis[0][0]||pathFound)return;
        path[totalPath--]=0;
      }
    }
  }
  if(minHeight+1!=height[u]){
    --gap[height[u]];
    if(gap[height[u]]==0)gridVis[0][0]=false;
    height[u]=minHeight+1;
    ++gap[height[u]];
  }
}

bool findPath(){
  pathFound=false;pred[0]=sinkNode;totalPath=0;path[0]=0;
  augmentPath(0,sinkNode);return pathFound;
}

void pushFlow(){
  for(int i=1;i<=totalPath;++i){
    if(path[i]>0)flow[abs(path[i-1])][path[i]]+=pred[0];
    else flow[-path[i]][abs(path[i-1])]-=pred[0];
  }
}

int main(){
  cin>>m>>limit;
  for(int i=1;i<=m;++i){
    cin>>input+1;
    for(int j=1;j<=m;++j){
      if(input[j]=='Z'){
        Point start={i,j,0};bfsQueue.push(start);
      }else if(input[j]!='Y'){
        gridVis[i][j]=true;origGrid[i][j]=true;
        dist[i][j]=limit;
        int val=input[j]-'0';
        if(val>0){
          a[i][j]=++totalNodes;
          cap[0][totalNodes]=val;
          sinkNode+=val;
        }
      }
    }
  }
  memcpy(origGrid,gridVis,sizeof(gridVis));
  for(int i=1;i<=m;++i){
    cin>>input+1;
    for(int j=1;j<=m;++j){
      if(input[j]=='Z'||input[j]=='Y')continue;
      int val=input[j]-'0';
      if(val>0){
        b[i][j]=++totalNodes;
        cap[totalNodes][m*m+1]=val;
      }
    }
  }
  if(totalNodes!=m*m){
    for(int i=1;i<=m;++i)
      for(int j=1;j<=m;++j)
        if(b[i][j]>0){
          int idx=b[i][j];
          cap[idx][totalNodes+1]=cap[idx][m*m+1];
          cap[idx][m*m+1]=0;
        }
  }
  while(!bfsQueue.empty()){
    Point cur=bfsQueue.front();bfsQueue.pop();
    int r=cur.r,c=cur.c;dist[r][c]=cur.dis;
    for(int k=0;k<4;++k)
      if(gridVis[r+dr[k]][c+dc[k]]){
        Point next={r+dr[k],c+dc[k],cur.dis+1};bfsQueue.push(next);
        gridVis[r+dr[k]][c+dc[k]]=false;
      }
  }
  for(int i=1;i<=m;++i)
    for(int j=1;j<=m;++j){
      if(a[i][j]==0)continue;
      memcpy(gridVis,origGrid,sizeof(origGrid));
      gridVis[i][j]=false;
      Point start={i,j,0};bfsQueue.push(start);
      while(!bfsQueue.empty()){
        Point cur=bfsQueue.front();bfsQueue.pop();
        int r=cur.r,c=cur.c;
        if(b[r][c]>0&&cur.dis<=dist[r][c])cap[a[i][j]][b[r][c]]=sinkNode;
        if(cur.dis+1>limit||cur.dis>=dist[r][c])continue;
        for(int k=0;k<4;++k)
          if(gridVis[r+dr[k]][c+dc[k]]){
            Point next={r+dr[k],c+dc[k],cur.dis+1};bfsQueue.push(next);
            gridVis[r+dr[k]][c+dc[k]]=false;
          }
      }
    }
  gap[0]=totalNodes+2;gridVis[0][0]=true;
  while(gridVis[0][0]&&height[0]<=totalNodes+2)
    while(findPath())pushFlow();
  int result=0;
  for(int i=1;i<=totalNodes;++i)result+=flow[i][totalNodes+1];
  cout<<result<<endl;return 0;
}
